import {notebookMarkup,bridgeMarkup} from './story-dialogue.js';
import {mountIronAffinity,resetIronAffinity} from './iron-affinity-workshop.js';
import {affinityBridge} from './affinity-bridge.js';
import {mountTerminology} from './terminology.js';
import {mountStoryEnding} from './story-ending.js';
import {savedLifeProgress} from './everyday-redox.js';
import {mountForgePrep} from './forge-prep.js';
import {upgradeInteractiveLab} from './lab-upgrade.js';
import {lessons,materialCases,freshState,restoreState,isReady,isMastered,migrateLegacy,migrateEight} from './journey-cards.js';
import {mountBurn} from './hands-on-burn.js';
import {mountNarrative} from './narrative-labs.js';
const $=id=>document.getElementById(id),storageKey='lost-forge-hands-on-7-v3';
let raw={},canStore=true,current=1,prepCount=0,lifeCount=savedLifeProgress();try{raw=JSON.parse(localStorage.getItem(storageKey)||'{}');}catch{canStore=false;}
let legacy={};try{legacy=JSON.parse(localStorage.getItem('lost-forge-hands-on-9-v1')||'{}');}catch{}
let previousEight={};try{previousEight=JSON.parse(localStorage.getItem('lost-forge-hands-on-8-v2')||'{}');}catch{}
const states=lessons.map(c=>raw[c.id]?restoreState(c,raw[c.id]):Object.keys(previousEight).length?migrateEight(c,previousEight):migrateLegacy(c,legacy)),cards=[];
const visibleLessons=lessons.filter(c=>c.id!==4);
const displayNumber=c=>c.id===1?'序章':String(visibleLessons.indexOf(c)+1).padStart(2,'0');
const mastered=c=>isMastered(c,states[c.id-1]);
function save(){try{localStorage.setItem(storageKey,JSON.stringify(Object.fromEntries(lessons.map(c=>[c.id,states[c.id-1]]))));}catch{canStore=false;}route();}
function route(){const n=visibleLessons.filter(mastered).length;$('top-progress').textContent=(n+prepCount+lifeCount)+' / '+(visibleLessons.length+4);$('mastery-label').textContent=(n+prepCount+lifeCount)+' / '+(visibleLessons.length+4);$('mastery-progress').max=visibleLessons.length+4;$('mastery-progress').value=n+prepCount+lifeCount;let act='';$('route').innerHTML=visibleLessons.map(c=>{const heading=act!==c.act?'<p class="route-act">'+c.act+'</p>':'';act=c.act;return (c.id===2?'<a class="prep-route" href="#forge-prep" '+(current==='prep'?'aria-current="step"':'')+'><span>01</span><span>煉鐵前的工坊試煉</span><i>'+(prepCount===3&&lifeCount?'✓':'○')+'</i></a>':'')+heading+`<a href="#card-${c.id}" ${current===c.id?'aria-current="step"':''} class="${mastered(c)?'mastered':''}"><span>${displayNumber(c)}</span><span>${c.title}</span><i aria-label="${mastered(c)?'已掌握':'待探索'}">${mastered(c)?'✓':isReady(c,states[c.id-1])?'◉':'○'}</i></a>`;}).join('')+'<a href="#story-ending" '+(current==='epilogue'?'aria-current="step"':'')+'><span>續章</span><span>鹽場的新難題</span><i>↗</i></a>';$('storage-note').textContent=canStore?'觀察與作答進度會自動保存。':'本次可正常操作，但瀏覽器無法保存進度。';}
function mount(c){const position=visibleLessons.indexOf(c),previous=visibleLessons[position-1],next=visibleLessons[position+1];const article=document.createElement('article');article.id='card-'+c.id;article.dataset.card=c.id;article.className='exploration-card hands-card';article.tabIndex=-1;article.setAttribute('aria-labelledby',article.id+'-title');$('lesson').append(article);cards.push(article);let s=states[c.id-1],epoch=0,timers=new Set(),cleanup=[];
 const find=selector=>article.querySelector(selector),has=k=>s.evidence.includes(k);
 function cancel(){epoch++;for(const t of timers)clearTimeout(t);timers.clear();for(const f of cleanup)f();cleanup=[];}
 function delay(fn,ms){const token=epoch;const t=setTimeout(()=>{timers.delete(t);if(token===epoch&&article.isConnected)fn();},matchMedia('(prefers-reduced-motion:reduce)').matches?Math.min(ms,80):ms);timers.add(t);}
 function record(k){if(!c.required.includes(k))return;if(!has(k))s.evidence.push(k);sync();save();}
 function notice(t){const status=find('.observation-status');if(status)status.textContent=t;}
 function renderLab(){cancel();notice('先讀取場景，再直接拖動物件，看看發生什麼。');const context={s,has,record,notice,delay,setCase:(key,autoLoad,spoonOrigin=null)=>{s.selected=key;s.autoLoad=autoLoad;s.spoonOrigin=spoonOrigin;renderLab();save();},onCleanup:f=>cleanup.push(f)};if(c.id===3){mountIronAffinity(find('.interactive-lab'),context);return;}if(['combustion','metals','nonmetals'].includes(c.type))mountBurn(find('.interactive-lab'),c,context);else mountNarrative(find('.interactive-lab'),c,context);cleanup.push(upgradeInteractiveLab(find('.interactive-lab'),c,context));find('.case-rack')?.querySelectorAll('[data-case]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.case===s.selected)));}
 function render(){article.innerHTML=`<header class="chapter-header"><div class="chapter-kicker"><span>${c.act}</span><div class="chapter-actions">${c.id===1?'':`<span>${c.day} · ${displayNumber(c)} / ${visibleLessons.length}</span>`}</div></div><h2 id="${article.id}-title">${c.title}</h2><p class="core-question">${c.question}</p></header><div class="chapter-body"><div class="story-scene-intro ${c.id===1?'with-forge-scene':''}">${c.id===1?$('locked-forge-scene').innerHTML:''}<div class="story-scene-copy">${c.opening?`<p class="opening">${c.opening}</p>`:''}<div class="story-dialogue" aria-label="小葵與阿公的對話">${c.dialogue.map(([who,line])=>`<div class="story-speech story-speech--${who}"><span class="story-portrait story-portrait--${who}" data-expression="${c.portraits[who]}" aria-hidden="true"></span><p><b>${who==='kui'?'小葵':'阿公'}</b>${line}</p></div>`).join('')}</div></div></div><div data-prediction-activity >${affinityBridge(c.id)}<div class="interaction-instruction"><span class="hand-icon">↔</span><p>${c.task}</p></div>${materialCases[c.type]&&!['combustion','redox','steel'].includes(c.type)?`<div class="case-rack" role="group" aria-label="選擇代表案例">${materialCases[c.type].map(([key,label])=>`<button data-case="${key}" aria-pressed="${s.selected===key}"><span class="case-symbol">${({CO:'C',ZnCu:'Zn',CuZn:'Cu',alone:'CuO',carbon:'C',wrought:'Fe',pig:'Fe–C',steel:'鋼',normal:'①',stress:'②'})[key]||key}</span><span>${label}</span></button>`).join('')}</div>`:''}${c.type==='combustion'?'<button class="studio-enter" data-enter-studio>進入實驗台，完整查看樣本與器材 ↘</button>':''}<div class="interactive-lab-frame"><div class="interaction-reset-bar"><button type="button" class="card-reset" data-reset aria-label="重設${displayNumber(c)}：${c.title}">↺ 重設本卡</button></div><div class="interactive-lab"></div></div>${[1,2,5,6].includes(c.id)?'':'<p class="observation-status" aria-live="polite"></p>'}</div><div class="evidence-panel"><span class="step-label">已留下的線索</span><ul class="evidence-list"></ul></div><section class="discovery" hidden>${[1,3].includes(c.id)?'':`<span class="step-label">把觀察連成解釋</span><h3>${c.conceptTitle}</h3><p class="observation-note"><b>你找到的現象</b>${c.finding}</p><ul class="concept-points">${c.points.map(p=>`<li>${p}</li>`).join('')}</ul>`}${[1,3].includes(c.id)?'':`<div class="reaction-equation">${c.equation.replaceAll('\n','<br>')}</div>`}</section>${[1,3].includes(c.id)?'':`<div class="chapter-bridge" hidden><span class="step-label">${!next?'接下新的委託':'接著探索 '+displayNumber(next)+'｜'+next.title}</span>${bridgeMarkup(c)}</div>`}${notebookMarkup(c.id)}<section class="practice" aria-labelledby="${article.id}-quiz"><span class="step-label">小試身手</span><h3 id="${article.id}-quiz">${c.quiz.question}</h3><div class="quiz-options">${c.quiz.options.map((text,i)=>`<button class="quiz-option" data-answer="${i}" aria-pressed="false"><span>${String.fromCharCode(65+i)}</span>${text}</button>`).join('')}</div><p class="feedback" aria-live="polite"></p></section></div><footer class="chapter-footer">${c.id>1?`<a class="previous" href="${c.id===2?'#forge-prep':'#card-'+previous.id}">← 上一張</a>`:''}<a class="next" href="${c.id===1?'#forge-prep':!next?'#story-ending':'#card-'+next.id}">${c.id===1?'先認識氧化與氧的轉移':!next?'獻上寶劍，聽見新的難題':'帶著線索往下走'} <b>→</b></a></footer>`;
 find('.case-rack')?.addEventListener('click',e=>{const b=e.target.closest('[data-case]');if(!b)return;s.selected=b.dataset.case;s.tab='burn';renderLab();save();});
 find('[data-enter-studio]')?.addEventListener('click',()=>{find('.combustion-studio').scrollIntoView({block:'start',behavior:'instant'});find('.combustion-studio').focus({preventScroll:true});});
 article.querySelectorAll('[data-reset]').forEach(b=>b.addEventListener('click',()=>{cancel();if(c.id===3)resetIronAffinity();s=freshState(c);states[c.id-1]=s;render();save();notice('已重設本卡，可以重新操作。');find('.interaction-reset-bar [data-reset]').focus({preventScroll:true});}));
 find('.quiz-options')?.addEventListener('click',e=>{const b=e.target.closest('[data-answer]');if(!b)return;s.quizOpen=true;s.answer=Number(b.dataset.answer);sync();save();});renderLab();sync();}
 function sync(){const ready=isReady(c,s);find('.evidence-list').innerHTML=c.required.map((k,i)=>`<li class="${has(k)?'done':''}"><span>${has(k)?'✓':'○'}</span>${c.labels[i]}</li>`).join('');find('.discovery').hidden=!ready||[1,3].includes(c.id);find('.chapter-bridge')?.toggleAttribute('hidden',!ready);find('.feedback').textContent=s.answer===null?'':(s.answer===c.quiz.answer?'✓ 答對了。':'再想一想。')+c.quiz.explanations[s.answer].replace(/^對。/,'')+(s.answer!==null&&s.answer!==c.quiz.answer?' 正確答案：'+String.fromCharCode(65+c.quiz.answer)+'，'+c.quiz.options[c.quiz.answer]+'。':'');find('.feedback').className='feedback '+(s.answer===null?'':s.answer===c.quiz.answer?'correct':'retry');find('.quiz-options').querySelectorAll('[data-answer]').forEach(b=>{const selected=Number(b.dataset.answer)===s.answer;b.setAttribute('aria-pressed',String(selected));b.classList.toggle('right',selected&&s.answer===c.quiz.answer);b.classList.toggle('wrong',selected&&s.answer!==c.quiz.answer);});}
 render();window.addEventListener('pagehide',cancel);
}

visibleLessons.forEach(mount);
$('card-6').before($('forged-sword-scene').content.cloneNode(true));
const prep=document.createElement('article');prep.id='forge-prep';prep.className='exploration-card';prep.tabIndex=-1;prep.dataset.card='prep';cards.splice(1,0,prep);prep.setAttribute('aria-labelledby','forge-prep-title');$('card-2').before(prep);prep.addEventListener('prep-progress',e=>{prepCount=e.detail;route();});prep.addEventListener('life-progress',e=>{lifeCount=e.detail;route();});mountForgePrep(prep);
route();
const epilogue=mountStoryEnding($('lesson'));epilogue.dataset.card='epilogue';cards.push(epilogue);
mountTerminology();

function activate(id){if(current===id)return;current=id;for(const a of $('route').querySelectorAll('a'))a.hash===(id==='epilogue'?'#story-ending':id==='prep'?'#forge-prep':id==='life'?'#everyday-redox':'#card-'+id)?a.setAttribute('aria-current','step'):a.removeAttribute('aria-current');}
window.addEventListener('hashchange',()=>{if(location.hash==='#card-4'){location.replace('#card-5');return;}if(location.hash==='#story-ending'){activate('epilogue');epilogue.focus({preventScroll:true});return;}if(location.hash==='#everyday-redox'){activate('prep');prep.focus({preventScroll:true});return;}if(location.hash==='#forge-prep'){activate('prep');prep.focus({preventScroll:true});return;}const id=Number(location.hash.replace('#card-',''));if(visibleLessons.some(c=>c.id===id)){activate(id);$('card-'+id).focus({preventScroll:true});}});
let frame=false;window.addEventListener('scroll',()=>{if(frame)return;frame=true;requestAnimationFrame(()=>{frame=false;let active=cards[0];for(const card of cards){if(card.getBoundingClientRect().top>innerHeight*.25)break;active=card;}activate(['prep','life','epilogue'].includes(active.dataset.card)?active.dataset.card:Number(active.dataset.card));});},{passive:true});
if(location.hash==='#card-4')history.replaceState(null,'','#card-5');
requestAnimationFrame(()=>{const target=document.querySelector(/^#(?:card-[1-9]|forge-prep|everyday-redox|story-ending)$/.test(location.hash)?location.hash:'#card-1');if(location.hash&&target){target.scrollIntoView({block:'start',behavior:'instant'});if(target.dataset.card)activate(['prep','life','epilogue'].includes(target.dataset.card)?target.dataset.card:Number(target.dataset.card));}});
